Here's a complete example:

**XAML (ItemsPage.xaml)**
```xml
<ContentPage xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             x:Class="MyApp.ItemsPage">

    <CollectionView ItemsSource="{Binding Items}"
                    SelectionMode="Single"
                    SelectedItem="{Binding SelectedItem}"
                    IsRefreshing="{Binding IsRefreshing}"
                    RemainingItemsThreshold="0">

        <!-- Pull-to-refresh via RefreshView wrapper -->
        <CollectionView.Behaviors>
            <!-- or wrap in RefreshView instead -->
        </CollectionView.Behaviors>
    </CollectionView>
</ContentPage>
```

The idiomatic approach is to wrap in a `RefreshView`:

```xml
<RefreshView Command="{Binding RefreshCommand}"
             IsRefreshing="{Binding IsRefreshing}">

    <CollectionView ItemsSource="{Binding Items}"
                    SelectionMode="Single"
                    SelectedItem="{Binding SelectedItem, Mode=TwoWay}">
        <CollectionView.ItemTemplate>
            <DataTemplate>
                <Grid Padding="10">
                    <Label Text="{Binding Name}" FontSize="16" />
                </Grid>
            </DataTemplate>
        </CollectionView.ItemTemplate>
    </CollectionView>

</RefreshView>
```

**ViewModel (ItemsViewModel.cs)**
```csharp
public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;
    private readonly INavigationService _nav;

    [ObservableProperty]
    private ObservableCollection<Item> _items = new();

    [ObservableProperty]
    private bool _isRefreshing;

    private Item? _selectedItem;
    public Item? SelectedItem
    {
        get => _selectedItem;
        set
        {
            if (SetProperty(ref _selectedItem, value) && value is not null)
            {
                // Navigate, then clear selection so user can re-select
                NavigateToDetail(value);
                SelectedItem = null;
            }
        }
    }

    [RelayCommand]
    private async Task Refresh()
    {
        var data = await _api.GetItemsAsync();
        Items = new ObservableCollection<Item>(data);
        IsRefreshing = false;           // stops the spinner
    }

    private async void NavigateToDetail(Item item)
    {
        await _nav.GoToAsync(nameof(DetailPage),
            new Dictionary<string, object> { ["Item"] = item });
    }
}
```

**Key bindings explained:**

| Binding | Direction | Purpose |
|---|---|---|
| `ItemsSource → Items` | OneWay | Displays the collection |
| `SelectedItem ↔ SelectedItem` | **TwoWay** | Detects selection, triggers navigation, then resets to `null` |
| `IsRefreshing ↔ IsRefreshing` | TwoWay | Controls the refresh spinner |
| `Command → RefreshCommand` | OneWay | Fires `Refresh()` on pull-down |

**Why reset `SelectedItem` to null?** Without it, tapping the same item twice won't fire the setter again since the value hasn't changed.
